const state = crypto.randomUUID();
session.set('notion_state', state);
redirect(notionAuthorizeUrl({ client_id, redirect_uri, response_type: 'code', owner: 'user', state }));

async function callback(req) {
  if (!req.query.code || req.query.state !== session.get('notion_state')) throw Error('Invalid OAuth state');
  const token = await postToken({ grant_type: 'authorization_code', code: req.query.code, redirect_uri });
  await secrets.upsert(connectionKey, encrypt(token));
}
